from lib import *
S = SS('t30')
steps = [
    step("没有状态表的编排器,崩溃之后什么都看不到。一个 saga 在“库存已预留、还没扣款”时 worker 进程消失了:要回答“lost-1 现在卡在哪一步”,得分别去问订单库(PENDING)、库存库(RESERVED)、支付库(0 条支付)。把三份数据拼起来能推断出“预留之后、扣款之前挂了”,但这是人的推断:没有人知道 worker 是死了还是只是在等,也不知道它重试了几次、上一次错误是什么。", t=tl(S(1)), mark=lidx(S(1), '订单 PENDING + 库存 RESERVED'), done=lidx(S(1), '要回答'), b=bars([['要查的库的数量', 3, '3(订单、库存、支付)'], ['能直接回答“卡在哪一步”的记录', 0, '0']], 3, cur=[0], mark=[1]), kv=KV([['订单库', 'PENDING'], ['库存库', 'RESERVED'], ['支付库', '0 条支付 → 靠人推断']], ['支付库'])),
    step("有了状态表。编排器把每个 saga 的当前步骤、状态、尝试次数、最后一个错误写进 saga_log,每次尝试一行写进 saga_step。1000 个 saga、16 个 worker,故障:扣款失败 15%(余额不足)、任何一步临时错误 8%(自带指数退避重试)、worker 在做完某一步之后悄悄消失 2%。1.0 s 跑完:worker 的返回值是 CONFIRMED 801、CANCELLED 179、WORKER_CRASHED 20。状态表里:确认 801、取消 179、在途 20(RUNNING),saga_step 一共 4296 行,其中临时失败的尝试 341 行。卡住的 20 个 saga,每个都能直接看到它停在哪一步(confirm / charge / reserve)和最后的错误。", t=tl(S(2)), mark=lidx(S(2), 'RUNNING 20', '卡住的'), done=lidx(S(2), '1000 个 saga', '从状态表里看'), b=bars([['CONFIRMED', 801, '801'], ['CANCELLED', 179, '179'], ['RUNNING(worker 崩溃留下的)', 20, '20'], ['临时失败的尝试(saga_step)', 341, '341']], 801, done=[0, 1], mark=[2], cur=[3]), kv=KV([['saga_log', '当前步骤、状态、最后错误一目了然'], ['saga_step', '4296 行,341 行临时失败'], ['worker 崩溃', '20 个 saga 停在 RUNNING']], ['saga_log'])),
    step("恢复守护进程:定时扫 saga_log,把“非终态、而且超过 1 秒没更新”的 saga 接管下来继续(用 UPDATE ... WHERE updated_at < ... 抢 owner,避免两个守护进程同时接管)。第一轮扫描接管并继续了 20 个 saga,第二轮 0 个。恢复之后:确认 821、取消 179、在途 0、COMPENSATION_FAILED 0。对账:库存仍被占着但订单不是 CONFIRMED 的 0 个,已扣款但订单是 CANCELLED 的 0 个。因为每一步都是幂等的(用 order_id 做主键),重新做“当前步骤”是安全的,哪怕 worker 其实已经做完了这一步只是没来得及记录。", t=tl(S(3)), mark=lidx(S(3), '第一轮扫描接管'), done=lidx(S(3), '恢复之后状态表', '对账'), b=bars([['第一轮接管', 20, '20'], ['第二轮接管', 0, '0'], ['恢复后在途', 0, '0'], ['恢复后对账发现的不一致', 0, '0']], 20, cur=[0], done=[1, 2, 3]), kv=KV([['接管', '抢 owner,第二个守护进程拿不到'], ['恢复', '从 saga_log 里记的步骤继续'], ['能安全重做', '每一步都是幂等的']], ['能安全重做'])),
    step("重试了几次、花了多久:预留库存这一步的尝试次数分布是 1 次 925 个、2 次 66 个、3 次 9 个。看创建到结束的耗时(不含被恢复守护进程接管过的,它们多等了一段被丢下的时间):没有临时失败的 709 个 saga,中位数 4 ms、p99 59 ms;至少一次临时失败的 271 个,中位数 30 ms、p99 101 ms。带指数退避的重试让有临时失败的 saga 变慢,但都走完了;saga_step 里能直接查到每个 saga 在哪一步试了几次、每次什么错。", t=tl(S(4)), mark=lidx(S(4), '至少一次临时失败'), done=lidx(S(4), '没有临时失败', '预留库存这一步'), b=bars([['没有临时失败 中位数 ms', 4, '4'], ['至少一次临时失败 中位数 ms', 30, '30'], ['没有临时失败 p99 ms', 59, '59'], ['至少一次临时失败 p99 ms', 101, '101']], 105, cur=[0, 2], mark=[1, 3]), kv=KV([['预留尝试次数', '1 次 925、2 次 66、3 次 9'], ['有临时失败', '中位数 4 → 30 ms'], ['查得到', '每个 saga 每一步每次尝试']], ['查得到'])),
    step("告警:模拟支付服务整整中断 3 秒(1.0 s 到 4.0 s,这段时间每次扣款都临时失败),600 个 saga 以 150 个/秒进来,24 个 worker 处理,恢复守护进程每 0.4 秒最多接管 8 个超过 1 秒没更新的 saga。每 0.5 秒取一次指标:在途 saga 从 2 涨到 24、48(2.0 s 时第一次触发“在途 > 40”的告警)、113(4.0 s 的峰值),最老的非终态 saga 越来越久没更新(4.0 s 时 2.3 s)。支付恢复后已确认从 130 涨到 478,但守护进程接管的速度有限(一共接管了 104 个),在途数从 80 慢慢降到 0,告警直到 9.1 s 才解除;最终 600 个 saga 全部 CONFIRMED。告警能在故障发生后 1 秒内发现问题,恢复的速度取决于守护进程接管得有多快。", t=tl(S(5)), mark=lidx(S(5), '2.0 s |', '4.0 s |'), done=lidx(S(5), '9.6 s |', '支付服务在 1.0 s'), b=bars([['峰值在途 saga(4.0 s)', 113, '113'], ['第一次告警时刻 s', 2.0, '2.0'], ['告警解除时刻 s', 9.1, '9.1'], ['守护进程接管的 saga', 104, '104']], 113, mark=[0, 1], done=[2], cur=[3]), kv=KV([['中断 3 秒', '在途 2 → 113,最老的 2.3 s 没更新'], ['告警', '2.0 s 触发,9.1 s 解除'], ['恢复速度', '守护进程接管 104 个,决定多久回落']], ['恢复速度'])),
]
A = mkartt('t30', 30, '分布式事务,Saga,可观测性,状态表,重试,恢复,告警,MySQL,真实验证,动画演示',
    '用 saga_log 与 saga_step 状态表让 Saga 可观测:1000 个 saga 在 worker 崩溃、临时失败下可以看到每个卡住的 saga 停在哪一步;恢复守护进程抢 owner 接管后 20 个全部走完、对账 0 不一致;支付服务中断 3 秒时在途数涨到 113,2.0 s 触发告警,守护进程接管 104 个,告警 9.1 s 解除。',
    'Saga 一旦跑起来,谁知道它们卡在哪一步?worker 崩溃了怎么发现、怎么接着做?重试了几次、花了多久?什么时候该报警?这篇用 saga_log / saga_step 两张状态表,配上恢复守护进程和几条监控查询,在真实的 MySQL 上把这些问题量出来。',
    [('20 → 0', 'worker 悄悄消失后停在 RUNNING 的 saga 数 → 恢复守护进程接管之后(对账 0 不一致)'), ('113', '支付服务中断 3 秒时,在途 saga 数的峰值(告警 2.0 s 触发)'), ('9.1 s', '告警解除的时刻(支付 4.0 s 恢复后,守护进程每 0.4 秒最多接管 8 个,恢复比中断本身还慢)')],
    [('没有状态表', '<p>只能跨三个服务的库拼出一个 saga 的位置,不知道它还活着没有、重试了几次。</p>'),
     ('状态表', '<p>saga_log 记当前步骤、状态、最后错误,saga_step 每次尝试一行;卡住的 saga 一眼可见。</p>'),
     ('恢复守护进程', '<p>扫非终态、久未更新的 saga,抢 owner 接管,从记录的步骤继续;每一步幂等才安全。</p>'),
     ('重试的账', '<p>尝试次数分布和耗时都能从 saga_step 查;有临时失败的 saga 更慢但都走完。</p>'),
     ('告警', '<p>在途数和最老非终态年龄两个指标能在中断 1 秒内触发告警;恢复速度由守护进程的接管能力决定。</p>')],
    steps,
    [ENV_T + '。本篇三个服务的库是同一个 MySQL 26.7.0 里的 schema(order_db / stock_db / pay_db),编排器的状态表在 saga_db;编排器、worker、恢复守护进程、监控采样都是我写的 Python 线程,不是 Seata / Temporal 等产品;故障是用固定种子的随机数在服务调用里注入的(临时失败、余额不足、worker 做完某步后“悄悄消失”),支付中断用时间窗口模拟;告警规则的阈值(在途 40、2 秒)是我设的',
     '没有验证:真正的进程崩溃(这里 worker “消失”是线程直接返回,不是 kill -9);恢复守护进程自己崩溃后的接管(这里只有一个守护进程循环);多个编排器实例并发的 saga 抢占;saga_step 表的清理与大小;和真实监控系统(Prometheus 等)的对接;COMPENSATION_FAILED 在本篇负载里一次都没有出现,没有用它演示人工处理流程(见第 9 篇)'],
    'Saga 的可观测性')
